    /// Replaces a recurring master and its exceptions in one transaction.
    ///
    /// CalDAV represents a series as a single resource, so a failed occurrence
    /// update must never leave the master (or its prior exceptions) changed.
    pub async fn replace_recurring_series(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        series_id: i64,
        change: RecurringSeriesChange,
    ) -> Result<EventProjection, EventServiceError> {
        validate_mutation(&change.event)?;
        for exception in &change.exceptions {
            match exception {
                RecurringExceptionChange::UpdateTimed(change) => {
                    validate_mutation(&change.event)?;
                    if !matches!(change.event.timing, EventTiming::Timed { .. }) {
                        return Err(EventServiceError::InvalidInput);
                    }
                }
                RecurringExceptionChange::UpdateAllDay(change) => {
                    validate_mutation(&change.event)?;
                    if !matches!(change.event.timing, EventTiming::AllDay { .. }) {
                        return Err(EventServiceError::InvalidInput);
                    }
                }
                RecurringExceptionChange::DeleteTimed(_) | RecurringExceptionChange::DeleteAllDay(_) => {}
            }
        }
        let now = (self.clock)();
        let timing = StoredTiming::from(&change.event.timing);
        let mut transaction = self.pool.begin_with("BEGIN IMMEDIATE").await?;
        authorize_in_transaction(
            &mut transaction,
            actor_user_id,
            is_superadmin,
            calendar_id,
            CalendarAction::EditAnyEvent,
        )
        .await?;
        ensure_not_imported(&mut transaction, series_id).await?;

        let result = sqlx::query(
            "UPDATE events
             SET title = ?, description = ?, location = ?, status = ?, event_kind = ?,
                 timed_start_utc = ?, timed_end_utc = ?, event_timezone = ?,
                 all_day_start_date = ?, all_day_end_date = ?,
                 last_edited_by_user_id = ?, version = version + 1, updated_at = ?
             WHERE calendar_id = ? AND id = ? AND recurrence_rule IS NOT NULL AND version = ?",
        )
        .bind(&change.event.title)
        .bind(&change.event.description)
        .bind(&change.event.location)
        .bind(change.event.status.as_str())
        .bind(timing.kind)
        .bind(timing.timed_start_utc)
        .bind(timing.timed_end_utc)
        .bind(timing.timezone)
        .bind(timing.all_day_start_date)
        .bind(timing.all_day_end_date)
        .bind(actor_user_id)
        .bind(now)
        .bind(calendar_id)
        .bind(series_id)
        .bind(change.expected_version)
        .execute(&mut *transaction)
        .await?;
        if result.rows_affected() != 1 {
            let current_version: Option<i64> = sqlx::query_scalar(
                "SELECT version FROM events WHERE calendar_id = ? AND id = ? AND recurrence_rule IS NOT NULL",
            )
            .bind(calendar_id)
            .bind(series_id)
            .fetch_optional(&mut *transaction)
            .await?;
            return match current_version {
                Some(current_version) => Err(EventServiceError::Conflict { current_version }),
                None => Err(EventServiceError::NotFound),
            };
        }
        sqlx::query("DELETE FROM event_recurrence_exceptions WHERE series_id = ?")
            .bind(series_id)
            .execute(&mut *transaction)
            .await?;

        for (version, exception) in (change.expected_version + 1..).zip(change.exceptions) {
            match exception {
                RecurringExceptionChange::UpdateTimed(change) => {
                    ensure_series_occurrence(&mut transaction, calendar_id, series_id, change.recurrence_id).await?;
                    bump_series_version(&mut transaction, calendar_id, series_id, version, actor_user_id, now).await?;
                    insert_timed_exception(&mut transaction, series_id, change.recurrence_id, &change.event, actor_user_id, now).await?;
                }
                RecurringExceptionChange::UpdateAllDay(change) => {
                    ensure_all_day_series_occurrence(&mut transaction, calendar_id, series_id, &change.recurrence_date).await?;
                    bump_series_version(&mut transaction, calendar_id, series_id, version, actor_user_id, now).await?;
                    insert_all_day_exception(&mut transaction, series_id, &change.recurrence_date, &change.event, actor_user_id, now).await?;
                }
                RecurringExceptionChange::DeleteTimed(recurrence_id) => {
                    ensure_series_occurrence(&mut transaction, calendar_id, series_id, recurrence_id).await?;
                    bump_series_version(&mut transaction, calendar_id, series_id, version, actor_user_id, now).await?;
                    insert_deleted_timed_exception(&mut transaction, series_id, recurrence_id, actor_user_id, now).await?;
                }
                RecurringExceptionChange::DeleteAllDay(recurrence_date) => {
                    ensure_all_day_series_occurrence(&mut transaction, calendar_id, series_id, &recurrence_date).await?;
                    bump_series_version(&mut transaction, calendar_id, series_id, version, actor_user_id, now).await?;
                    insert_deleted_all_day_exception(&mut transaction, series_id, &recurrence_date, actor_user_id, now).await?;
                }
            }
        }
        insert_event_audit(&mut transaction, actor_user_id, "event.update", series_id, now).await?;
        record_caldav_change(&mut transaction, calendar_id, series_id, "updated", now, None).await?;
        transaction.commit().await?;
        self.notification_replanner.send(series_id).await;
        self.get(actor_user_id, is_superadmin, calendar_id, series_id).await
    }

    pub async fn create_recurring(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        event: EventMutation,
        recurrence_rule: String,
    ) -> Result<EventProjection, EventServiceError> {
        validate_mutation(&event)?;
        validate_recurrence(&event, &recurrence_rule)?;
        let now = (self.clock)();
        let timing = StoredTiming::from(&event.timing);
        let mut transaction = self.pool.begin_with("BEGIN IMMEDIATE").await?;
        authorize_in_transaction(
            &mut transaction,
            actor_user_id,
            is_superadmin,
            calendar_id,
            CalendarAction::CreateEvent,
        )
        .await?;
        let result = sqlx::query(
            "INSERT INTO events (
                calendar_id, title, description, location, status, event_kind,
                timed_start_utc, timed_end_utc, event_timezone,
                all_day_start_date, all_day_end_date, created_by_user_id,
                last_edited_by_user_id, version, created_at, updated_at, recurrence_rule
             ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)",
        )
        .bind(calendar_id)
        .bind(&event.title)
        .bind(&event.description)
        .bind(&event.location)
        .bind(event.status.as_str())
        .bind(timing.kind)
        .bind(timing.timed_start_utc)
        .bind(timing.timed_end_utc)
        .bind(timing.timezone)
        .bind(timing.all_day_start_date)
        .bind(timing.all_day_end_date)
        .bind(actor_user_id)
        .bind(actor_user_id)
        .bind(now)
        .bind(now)
        .bind(&recurrence_rule)
        .execute(&mut *transaction)
        .await?;
        let event_id = result.last_insert_rowid();
        insert_event_audit(
            &mut transaction,
            actor_user_id,
            "event.series.create",
            event_id,
            now,
        )
        .await?;
        record_caldav_change(
            &mut transaction,
            calendar_id,
            event_id,
            "created",
            now,
            None,
        )
        .await?;
        transaction.commit().await?;
        self.notification_replanner.send(event_id).await;
        let mut projection = self
            .get(actor_user_id, is_superadmin, calendar_id, event_id)
            .await?;
        projection.recurrence_rule = Some(recurrence_rule);
        Ok(projection)
    }

    pub async fn create_batch(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        batch: EventCreateBatch,
    ) -> Result<EventCreateBatchResult, EventServiceError> {
        validate_create_batch(&batch)?;
        let now = (self.clock)();
        let mut transaction = self.pool.begin_with("BEGIN IMMEDIATE").await?;
        authorize_in_transaction(
            &mut transaction,
            actor_user_id,
            is_superadmin,
            calendar_id,
            CalendarAction::CreateEvent,
        )
        .await?;

        let mut event_ids = Vec::with_capacity(batch.events.len());
        let mut exception_count = 0;
        for item in batch.events {
            let timing = StoredTiming::from(&item.event.timing);
            let result = sqlx::query(
                "INSERT INTO events (
                    calendar_id, title, description, location, status, event_kind,
                    timed_start_utc, timed_end_utc, event_timezone,
                    all_day_start_date, all_day_end_date, created_by_user_id,
                    last_edited_by_user_id, version, created_at, updated_at, recurrence_rule
                 ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)",
            )
            .bind(calendar_id)
            .bind(&item.event.title)
            .bind(&item.event.description)
            .bind(&item.event.location)
            .bind(item.event.status.as_str())
            .bind(timing.kind)
            .bind(timing.timed_start_utc)
            .bind(timing.timed_end_utc)
            .bind(timing.timezone)
            .bind(timing.all_day_start_date)
            .bind(timing.all_day_end_date)
            .bind(actor_user_id)
            .bind(actor_user_id)
            .bind(now)
            .bind(now)
            .bind(&item.recurrence_rule)
            .execute(&mut *transaction)
            .await?;
            let event_id = result.last_insert_rowid();

            for exception in item.exceptions {
                let (recurrence_id, recurrence_date) = match exception.recurrence {
                    EventRecurrenceKey::Timed(value) => (Some(value), None),
                    EventRecurrenceKey::AllDay(value) => (None, Some(value)),
                };
                let replacement = exception.replacement.as_ref();
                let replacement_timing = replacement.map(|event| StoredTiming::from(&event.timing));
                sqlx::query(
                    "INSERT INTO event_recurrence_exceptions (
                        series_id, recurrence_id, recurrence_date, is_deleted,
                        title, description, location, status,
                        timed_start_utc, timed_end_utc, event_timezone,
                        all_day_start_date, all_day_end_date,
                        last_edited_by_user_id, created_at, updated_at
                     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                )
                .bind(event_id)
                .bind(recurrence_id)
                .bind(recurrence_date)
                .bind(i64::from(replacement.is_none()))
                .bind(replacement.map(|event| event.title.as_str()))
                .bind(replacement.and_then(|event| event.description.as_deref()))
                .bind(replacement.and_then(|event| event.location.as_deref()))
                .bind(replacement.map(|event| event.status.as_str()))
                .bind(
                    replacement_timing
                        .as_ref()
                        .and_then(|timing| timing.timed_start_utc),
                )
                .bind(
                    replacement_timing
                        .as_ref()
                        .and_then(|timing| timing.timed_end_utc),
                )
                .bind(
                    replacement_timing
                        .as_ref()
                        .and_then(|timing| timing.timezone),
                )
                .bind(
                    replacement_timing
                        .as_ref()
                        .and_then(|timing| timing.all_day_start_date),
                )
                .bind(
                    replacement_timing
                        .as_ref()
                        .and_then(|timing| timing.all_day_end_date),
                )
                .bind(actor_user_id)
                .bind(now)
                .bind(now)
                .execute(&mut *transaction)
                .await?;
                exception_count += 1;
            }

            insert_event_audit(
                &mut transaction,
                actor_user_id,
                if item.recurrence_rule.is_some() {
                    "event.series.create"
                } else {
                    "event.create"
                },
                event_id,
                now,
            )
            .await?;
            event_ids.push(event_id);
        }

        transaction.commit().await?;
        for event_id in &event_ids {
            self.notification_replanner.send(*event_id).await;
        }
        Ok(EventCreateBatchResult {
            event_ids,
            exception_count,
        })
    }

    pub async fn get(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        event_id: i64,
    ) -> Result<EventProjection, EventServiceError> {
        let access = self
            .read_access(actor_user_id, is_superadmin, calendar_id)
            .await?;
        let event = EventRepository::new(self.pool.clone())
            .event(calendar_id, event_id)
            .await?
            .ok_or(EventServiceError::NotFound)?;
        let mut projection = project_event(event, access);
        if matches!(access, EventAccess::Details) {
            projection.recurrence_rule =
                sqlx::query_scalar("SELECT recurrence_rule FROM events WHERE id = ?")
                    .bind(event_id)
                    .fetch_optional(&self.pool)
                    .await?
                    .flatten();
        }
        mark_external_projections(&self.pool, std::slice::from_mut(&mut projection)).await?;
        Ok(projection)
    }

    pub async fn list(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        range: EventRange,
    ) -> Result<Vec<EventProjection>, EventServiceError> {
        let access = self
            .read_access(actor_user_id, is_superadmin, calendar_id)
            .await?;
        let mut projected: Vec<_> = EventRepository::new(self.pool.clone())
            .events_in_range(calendar_id, range.clone())
            .await?
            .into_iter()
            .map(|event| Ok(project_event(event, access)))
            .collect::<Result<_, EventServiceError>>()?;
        let mut recurring = self
            .expanded_recurring_events(calendar_id, &range, access)
            .await?;
        projected.append(&mut recurring);
        let mut all_day_recurring = self
            .expanded_all_day_events(calendar_id, &range, access)
            .await?;
        projected.append(&mut all_day_recurring);
        mark_external_projections(&self.pool, &mut projected).await?;
        projected.sort_by_key(|event| (event.start_utc.unwrap_or(i64::MIN), event.id));
        Ok(projected)
    }

    async fn expanded_recurring_events(
        &self,
        calendar_id: i64,
        range: &EventRange,
        access: EventAccess,
    ) -> Result<Vec<EventProjection>, EventServiceError> {
        let series = sqlx::query_as::<_, RecurringSeriesRecord>(
            "SELECT id, calendar_id, title, description, location, status,
                    timed_start_utc, timed_end_utc, event_timezone,
                    created_by_user_id, last_edited_by_user_id, version,
                    created_at, updated_at, recurrence_rule
             FROM events
             WHERE calendar_id = ? AND recurrence_rule IS NOT NULL AND event_kind = 'timed'",
        )
        .bind(calendar_id)
        .fetch_all(&self.pool)
        .await?;
        let mut expanded = Vec::new();
        for series in series {
            let exceptions = sqlx::query_as::<_, RecurrenceExceptionRecord>(
                "SELECT recurrence_id, is_deleted, title, description, location, status,
                        timed_start_utc, timed_end_utc, event_timezone
                 FROM event_recurrence_exceptions WHERE series_id = ?",
            )
            .bind(series.id)
            .fetch_all(&self.pool)
            .await?;
            let excluded: HashSet<_> = exceptions
                .iter()
                .filter(|exception| exception.is_deleted)
                .filter_map(|exception| Utc.timestamp_opt(exception.recurrence_id, 0).single())
                .collect();
            let modified: HashMap<_, _> = exceptions
                .iter()
                .filter(|exception| !exception.is_deleted)
                .filter_map(|exception| {
                    Some((
                        Utc.timestamp_opt(exception.recurrence_id, 0).single()?,
                        ModifiedOccurrence {
                            start: Utc.timestamp_opt(exception.timed_start_utc?, 0).single()?,
                            end: Utc.timestamp_opt(exception.timed_end_utc?, 0).single()?,
                        },
                    ))
                })
                .collect();
            let timezone: Tz = series
                .event_timezone
                .parse()
                .map_err(|_| EventServiceError::InvalidInput)?;
            let starts_at = timezone.from_utc_datetime(
                &Utc.timestamp_opt(series.timed_start_utc, 0)
                    .single()
                    .ok_or(EventServiceError::InvalidInput)?
                    .naive_utc(),
            );
            let occurrences = expand_occurrences(
                &RecurringEvent {
                    starts_at,
                    duration: Duration::seconds(series.timed_end_utc - series.timed_start_utc),
                    rule: RecurrenceRule::parse(&series.recurrence_rule)
                        .map_err(|_| EventServiceError::InvalidInput)?,
                },
                TimeInterval {
                    start: Utc
                        .timestamp_opt(range.start_utc, 0)
                        .single()
                        .ok_or(EventServiceError::InvalidInput)?,
                    end: Utc
                        .timestamp_opt(range.end_utc, 0)
                        .single()
                        .ok_or(EventServiceError::InvalidInput)?,
                },
                &excluded,
                &modified,
                ExpansionLimits::default(),
            )
            .map_err(|_| EventServiceError::InvalidInput)?;
            for occurrence in occurrences {
                let exception = exceptions.iter().find(|exception| {
                    exception.recurrence_id == occurrence.recurrence_id.timestamp()
                        && !exception.is_deleted
                });
                expanded.push(project_occurrence(&series, exception, occurrence, access)?);
            }
        }
        Ok(expanded)
    }

    async fn expanded_all_day_events(
        &self,
        calendar_id: i64,
        range: &EventRange,
        access: EventAccess,
    ) -> Result<Vec<EventProjection>, EventServiceError> {
        let series = sqlx::query_as::<_, AllDaySeriesRecord>(
            "SELECT id, calendar_id, title, description, location, status,
                    all_day_start_date, all_day_end_date,
                    created_by_user_id, last_edited_by_user_id, version,
                    created_at, updated_at, recurrence_rule
             FROM events
             WHERE calendar_id = ? AND recurrence_rule IS NOT NULL
               AND event_kind = 'all_day'",
        )
        .bind(calendar_id)
        .fetch_all(&self.pool)
        .await?;
        let requested = TimeInterval {
            start: date_at_utc(&range.start_date)?,
            end: date_at_utc(&range.end_date)?,
        };
        let mut expanded = Vec::new();
        for series in series {
            let exceptions = sqlx::query_as::<_, AllDayExceptionRecord>(
                "SELECT recurrence_date, is_deleted, title, description, location, status,
                        all_day_start_date, all_day_end_date
                 FROM event_recurrence_exceptions
                 WHERE series_id = ? AND recurrence_date IS NOT NULL",
            )
            .bind(series.id)
            .fetch_all(&self.pool)
            .await?;
            let excluded: HashSet<_> = exceptions
                .iter()
                .filter(|exception| exception.is_deleted)
                .map(|exception| date_at_utc(&exception.recurrence_date))
                .collect::<Result<_, _>>()?;
            let modified: HashMap<_, _> = exceptions
                .iter()
                .filter(|exception| !exception.is_deleted)
                .map(|exception| {
                    Ok((
                        date_at_utc(&exception.recurrence_date)?,
                        ModifiedOccurrence {
                            start: date_at_utc(
                                exception
                                    .all_day_start_date
                                    .as_deref()
                                    .ok_or(EventServiceError::InvalidInput)?,
                            )?,
                            end: date_at_utc(
                                exception
                                    .all_day_end_date
                                    .as_deref()
                                    .ok_or(EventServiceError::InvalidInput)?,
                            )?,
                        },
                    ))
                })
                .collect::<Result<_, EventServiceError>>()?;
            let starts_at_utc = date_at_utc(&series.all_day_start_date)?;
            let ends_at_utc = date_at_utc(&series.all_day_end_date)?;
            let starts_at = chrono_tz::UTC.from_utc_datetime(&starts_at_utc.naive_utc());
            let occurrences = expand_occurrences(
                &RecurringEvent {
                    starts_at,
                    duration: ends_at_utc - starts_at_utc,
                    rule: RecurrenceRule::parse(&series.recurrence_rule)
                        .map_err(|_| EventServiceError::InvalidInput)?,
                },
                requested,
                &excluded,
                &modified,
                ExpansionLimits::default(),
            )
            .map_err(|_| EventServiceError::InvalidInput)?;
            for occurrence in occurrences {
                let recurrence_date = occurrence
                    .recurrence_id
                    .date_naive()
                    .format("%Y-%m-%d")
                    .to_string();
                let exception = exceptions.iter().find(|exception| {
                    exception.recurrence_date == recurrence_date && !exception.is_deleted
                });
                expanded.push(project_all_day_occurrence(
                    &series, exception, occurrence, access,
                )?);
            }
        }
        Ok(expanded)
    }

